import java.nio.file.Path;
import java.sql.DriverManager;
import liquibase.*;
import liquibase.database.DatabaseFactory;
import liquibase.database.jvm.JdbcConnection;
import liquibase.resource.DirectoryResourceAccessor;
/** Actual BP1 Liquibase last-change rollback/reapply and populated-metadata guard. */
public class NigeriaMigrationProbe {
 static String state(java.sql.Connection connection)throws Exception{try(var statement=connection.createStatement();var rows=statement.executeQuery("SELECT md5(string_agg(value,'|' ORDER BY value)) FROM (SELECT row_to_json(m)::text value FROM commerce.market m WHERE code='NG' UNION ALL SELECT row_to_json(d)::text FROM commerce.market_destination d JOIN commerce.market m ON m.id=d.market_id WHERE m.code='NG' UNION ALL SELECT row_to_json(c)::text FROM commerce.currency c WHERE code='NGN') x")){rows.next();return rows.getString(1);}}
 public static void main(String[] args)throws Exception{boolean guard=args.length==1&&args[0].equals("guard");try(var connection=DriverManager.getConnection("jdbc:postgresql://postgres:5432/nigson","nigson_commerce_migrator",System.getenv("MIGRATION_PASSWORD"));var resources=new DirectoryResourceAccessor(Path.of("/app/source"))){var database=DatabaseFactory.getInstance().findCorrectDatabaseImplementation(new JdbcConnection(connection));database.setDefaultSchemaName("commerce");database.setLiquibaseSchemaName("commerce");try(var migration=new Liquibase("services/commerce/src/main/resources/db/changelog/master.yaml",resources,database)){migration.setChangeLogParameter("schema.release","BP1");String before=state(connection);if(guard){boolean rejected=false;try{migration.rollback(1,new Contexts(),new LabelExpression());}catch(liquibase.exception.LiquibaseException expected){rejected=true;}if(!rejected||!java.util.Objects.equals(before,state(connection)))throw new IllegalStateException("POPULATED_ROLLBACK_GUARD_FAILED");}else{migration.rollback(1,new Contexts(),new LabelExpression());try(var statement=connection.createStatement();var rows=statement.executeQuery("SELECT count(*) FROM commerce.market WHERE code='NG'")){rows.next();if(rows.getInt(1)!=0)throw new IllegalStateException("NG_BASELINE_ROLLBACK_FAILED");}migration.update(new Contexts(),new LabelExpression());migration.validate();try(var statement=connection.createStatement();var rows=statement.executeQuery("SELECT count(*) FROM commerce.market m JOIN commerce.currency c ON c.code=m.currency_code JOIN commerce.market_destination d ON d.market_id=m.id WHERE m.code='NG' AND NOT m.enabled AND c.code='NGN' AND c.minor_unit=2 AND c.active AND d.country_code='NG' AND NOT d.delivery_enabled")){rows.next();if(rows.getInt(1)!=1)throw new IllegalStateException("NG_BASELINE_REAPPLY_FAILED");}}System.out.println("PASS: actual BP1 Liquibase Nigeria "+(guard?"populated rollback guard":"pristine rollback/reapply"));}}}
}
